encounterTypes.entityEligibilityCheckRule:
'use strict';
({params, imports}) => {
    const individual = params.entity;
    const moment = imports.moment;
    let eligibility = true;

    const isInActiveProgramBatch = individual.groups.some(group => group.voided == false && group.membershipEndDate == null && group.groupSubject.enrolments.some(enrolment => enrolment.program.name == "D_Vriddhi" && enrolment.isActive));

    eligibility = isInActiveProgramBatch;

    return eligibility;
};

formElements.rule:
'use strict';
({params, imports}) => {
  const programEncounter = params.entity;
  const moment = imports.moment;
  const formElement = params.formElement;
  let validationErrors = [];
  const userGroups = params.myUserGroups.map((grp) => grp.groupName);
  const isAdministrator = userGroups.includes('Administrators');

  if (!isAdministrator && moment(programEncounter.encounterDateTime).isBefore(moment(), 'day')){
      validationErrors.push('You cannot upload attendance in backdate');
  }

  return new imports.rulesConfig.FormElementStatus(formElement.uuid, true, null, [], validationErrors);
};

